  /**
   * set matrix from two direction
   * @param fromDirection first direction
   * @param toDirection second direction
   */
  transformDir(fromDirection, toDirection) {
    let data = this.rawData;
    let EPSILON2 = 1e-6;
    let v = Vector3.ZERO;
    toDirection.crossProduct(fromDirection, v);
    let e = toDirection.dotProduct(fromDirection);
    if (e > 1 - EPSILON2) {
      this.identity();
    } else if (e < -1 + EPSILON2) {
      let up = Vector3.HELP_1;
      let left = Vector3.HELP_2;
      let invLen = 0;
      let fxx;
      let fyy;
      let fzz;
      let fxy;
      let fxz;
      let fyz;
      let uxx;
      let uyy;
      let uzz;
      let uxy;
      let uxz;
      let uyz;
      let lxx;
      let lyy;
      let lzz;
      let lxy;
      let lxz;
      let lyz;
      left.x = 0;
      left.y = fromDirection.z;
      left.z = -fromDirection.y;
      if (left.dotProduct(left) < EPSILON2) {
        left.x = -fromDirection.z;
        left.y = 0;
        left.z = fromDirection.x;
      }
      invLen = 1 / Math.sqrt(left.dotProduct(left));
      left.x *= invLen;
      left.y *= invLen;
      left.z *= invLen;
      left.crossProduct(fromDirection, up);
      fxx = -fromDirection.x * fromDirection.x;
      fyy = -fromDirection.y * fromDirection.y;
      fzz = -fromDirection.z * fromDirection.z;
      fxy = -fromDirection.x * fromDirection.y;
      fxz = -fromDirection.x * fromDirection.z;
      fyz = -fromDirection.y * fromDirection.z;
      uxx = up.x * up.x;
      uyy = up.y * up.y;
      uzz = up.z * up.z;
      uxy = up.x * up.y;
      uxz = up.x * up.z;
      uyz = up.y * up.z;
      lxx = -left.x * left.x;
      lyy = -left.y * left.y;
      lzz = -left.z * left.z;
      lxy = -left.x * left.y;
      lxz = -left.x * left.z;
      lyz = -left.y * left.z;
      data[0] = fxx + uxx + lxx;
      data[1] = fxy + uxy + lxy;
      data[2] = fxz + uxz + lxz;
      data[4] = data[1];
      data[5] = fyy + uyy + lyy;
      data[6] = fyz + uyz + lyz;
      data[8] = data[2];
      data[9] = data[6];
      data[10] = fzz + uzz + lzz;
      data[3] = 0;
      data[7] = 0;
      data[11] = 0;
      data[15] = 1;
    } else {
      let hvx;
      let hvz;
      let hvxy;
      let hvxz;
      let hvyz;
      let v2 = v.dotProduct(v);
      let h = (1 - e) / v2;
      hvx = h * v.x;
      hvz = h * v.z;
      hvxy = hvx * v.y;
      hvxz = hvx * v.z;
      hvyz = hvz * v.y;
      data[0] = e + hvx * v.x;
      data[1] = hvxy - v.z;
      data[2] = hvxz + v.y;
      data[4] = hvxy + v.z;
      data[5] = e + h * v.y * v.y;
      data[6] = hvyz - v.x;
      data[8] = hvxz - v.y;
      data[9] = hvyz + v.x;
      data[10] = e + hvz * v.z;
      data[3] = 0;
      data[7] = 0;
      data[11] = 0;
      data[15] = 1;
    }
    return this;
  }
