  /**
   Add a direction Angle rotation to the current matrix (the matrix created by rotating degrees according to axis)
   @param degrees Angle of rotation.
   @param axis Angle of rotation around axis axis
   @version Orillusion3D  0.5.1
  */
  appendRotation(degrees, axis) {
    let m = Matrix4.getAxisRotation(axis.x, axis.y, axis.z, degrees);
    this.append(m);
  }
  /**
   * Create a matrix based on the axis and rotation Angle (the matrix created by rotating the degrees according to the axis)
   * @param degrees Angle of rotation.
   * @param axis Rotation Angle around axis axis. Axis needs to be specified as the orientation of an axis between x/y/z
   */
  createByRotation(degrees, axis) {
    let tmp = Matrix4.helpMatrix;
    let s;
    let c;
    let angle = degrees * DEGREES_TO_RADIANS;
    s = Math.sin(angle);
    c = Math.cos(angle);
    if (axis.x == 1) {
      tmp.rawData[0] = 1;
      tmp.rawData[1] = 0;
      tmp.rawData[2] = 0;
      tmp.rawData[3] = 0;
      tmp.rawData[4] = 0;
      tmp.rawData[5] = c;
      tmp.rawData[6] = s;
      tmp.rawData[7] = 0;
      tmp.rawData[8] = 0;
      tmp.rawData[9] = -s;
      tmp.rawData[10] = c;
      tmp.rawData[11] = 0;
      tmp.rawData[12] = 0;
      tmp.rawData[13] = 0;
      tmp.rawData[14] = 0;
      tmp.rawData[15] = 1;
    }
    if (axis.y == 1) {
      tmp.rawData[0] = c;
      tmp.rawData[1] = 0;
      tmp.rawData[2] = -s;
      tmp.rawData[3] = 0;
      tmp.rawData[4] = 0;
      tmp.rawData[5] = 1;
      tmp.rawData[6] = 0;
      tmp.rawData[7] = 0;
      tmp.rawData[8] = s;
      tmp.rawData[9] = 0;
      tmp.rawData[10] = c;
      tmp.rawData[11] = 0;
      tmp.rawData[12] = 0;
      tmp.rawData[13] = 0;
      tmp.rawData[14] = 0;
      tmp.rawData[15] = 1;
    }
    if (axis.z == 1) {
      tmp.rawData[0] = c;
      tmp.rawData[1] = s;
      tmp.rawData[2] = 0;
      tmp.rawData[3] = 0;
      tmp.rawData[4] = -s;
      tmp.rawData[5] = c;
      tmp.rawData[6] = 0;
      tmp.rawData[7] = 0;
      tmp.rawData[8] = 0;
      tmp.rawData[9] = 0;
      tmp.rawData[10] = 1;
      tmp.rawData[11] = 0;
      tmp.rawData[12] = 0;
      tmp.rawData[13] = 0;
      tmp.rawData[14] = 0;
      tmp.rawData[15] = 1;
    }
    this.append(tmp);
    return this;
  }
