    this.outlineTex.resize(w, h);
    this.weightBuffer.resizeBuffer(this.lowTexSize.x * this.lowTexSize.y * 4);
    this.oldOutlineColor.resizeBuffer(this.lowTexSize.x * this.lowTexSize.y * 4);
