class DoubleArray {
  _keys = new Array();
  _values = new Array();
  getIndexByKey(key) {
    return this._keys.indexOf(key);
  }
  getValueByKey(key) {
    var index = this.getIndexByKey(key);
    if (index > -1) {
      return this._values[index];
    }
    return null;
  }
  put(key, value) {
    if (key == null)
      return null;
    var old = this.remove(key);
    this._keys.push(key);
    this._values.push(value);
    return old;
  }
  remove(key) {
    var index = this._keys.indexOf(key);
    var item;
    if (index > -1) {
      item = this._values[index];
      this._keys.splice(index, 1);
      this._values.splice(index, 1);
    }
    return item;
  }
  getValues() {
    return this._values;
  }
  getKeys() {
    return this._keys;
  }
  clear() {
    this._values.length = 0;
    this._keys.length = 0;
  }
}

