      Navi3DEdge.CALC_FAT_VECTOR.copyFrom(this._edgeDirA2B);
      Navi3DEdge.CALC_FAT_VECTOR.scaleBy(-radius);
      Navi3DEdge.CALC_FAT_VECTOR.incrementBy(this._pointB);
