class GridObject extends Object3D {
  size = 100;
  divisions = 10;
  constructor(size = 100, divisions = 10) {
    super();
    this.size = size;
    this.divisions = divisions;
    this.buildGeometry();
    this.addAxis();
  }
  buildGeometry() {
    const vertices = [];
    const indices = [];
    const step = this.size / this.divisions;
    const halfSize = this.size / 2;
    const center = this.divisions / 2;
    for (let i = 0, k = -halfSize; i <= this.divisions; i++, k += step) {
      if (i === center)
        continue;
      vertices.push(-halfSize, 0, k, halfSize, 0, k);
      vertices.push(k, 0, -halfSize, k, 0, halfSize);
    }
    for (let i = 0; i < vertices.length / 3; i += 2)
      indices.push(i, i + 1);
    let grid = new GeometryBase();
    grid.setIndices(indices.length > Uint16Array.length ? new Uint32Array(indices) : new Uint16Array(indices));
    grid.setAttribute(VertexAttributeName.position, new Float32Array(vertices));
    grid.addSubGeometry({
      indexStart: 0,
      indexCount: indices.length,
      vertexStart: 0,
      vertexCount: 0,
      firstStart: 0,
      index: 0,
      topology: 0
    });
    let mat = new UnLitMaterial();
    mat.topology = "line-list";
    mat.baseColor = new Color(1, 1, 1, 0.15);
    mat.blendMode = BlendMode.ADD;
    mat.castReflection = false;
    let mr = this.addComponent(MeshRenderer);
    mr.geometry = grid;
    mr.material = mat;
  }
  addAxis() {
    const halfSize = this.size / 2;
    let vertices = new Float32Array([-halfSize, 0, 0, halfSize, 0, 0]);
    let indexes = new Uint16Array([0, 1, 2, 3]);
    let line = new GeometryBase();
    line.setIndices(indexes);
    line.setAttribute(VertexAttributeName.position, vertices);
    line.addSubGeometry({
      indexStart: 0,
      indexCount: indexes.length,
      vertexStart: 0,
      vertexCount: 0,
      firstStart: 0,
      index: 0,
      topology: 0
    });
    {
      let x = new Object3D();
      let mr = x.addComponent(MeshRenderer);
      mr.geometry = line;
      let mat = mr.material = new UnLitMaterial();
      mat.baseColor = new Color(1, 0, 0, 0.5);
      mat.blendMode = BlendMode.ADD;
      mat.castReflection = false;
      mat.topology = "line-list";
      this.addChild(x);
    }
    {
      let z = new Object3D();
      z.rotationY = 90;
      let mr = z.addComponent(MeshRenderer);
      mr.geometry = line;
      let mat = mr.material = new UnLitMaterial();
      mat.baseColor = new Color(0, 1, 0, 0.5);
      mat.blendMode = BlendMode.ADD;
      mat.castReflection = false;
      mat.topology = "line-list";
      this.addChild(z);
    }
  }
}

class KelvinUtil {
  /**
   * Convert color temperature to color object
   * @param color_temperature_Kelvin Color temperature value
   * @returns
   */
  static color_temperature_to_rgb(color_temperature_Kelvin) {
    if (color_temperature_Kelvin < 1e3) {
      color_temperature_Kelvin = 1e3;
    } else if (color_temperature_Kelvin > 4e4) {
      color_temperature_Kelvin = 4e4;
    }
    let tmp_internal = color_temperature_Kelvin / 100;
    let red = this.get_red(tmp_internal);
    let green = this.get_green(tmp_internal);
    let blue = this.get_blue(tmp_internal);
    return new Color(red / 255, green / 255, blue / 255, 1);
  }
  /**
   * Return red component [0-255]
   * @param temperature
   * @returns
   */
  static get_red(temperature) {
    if (temperature <= 66) return 255;
    let tmp_red = 329.698727446 * Math.pow(temperature - 60, -0.1332047592);
    return this.bound(tmp_red);
  }
  /**
   * Return green component [0-255]
   * @param temperature
   * @returns
   */
  static get_green(temperature) {
    let green = 0;
    if (temperature <= 66) {
      green = 99.4708025861 * Math.log(temperature) - 161.1195681661;
    } else {
      green = 288.1221695283 * Math.pow(temperature - 60, -0.0755148492);
    }
    return this.bound(green);
  }
  /**
   * Return blue component [0-255]
   * @param temperature
   * @returns
   */
  static get_blue(temperature) {
    let blue = 0;
    if (temperature >= 66) {
      return 255;
    }
    if (temperature <= 19) {
      return 0;
    }
    blue = 138.5177312231 * Math.log(temperature - 10) - 305.0447927307;
    return this.bound(blue);
  }
  /**
   * @internal
   * @param color_component
   * @param minimum
   * @param maximum
   * @returns
   */
  static bound(color_component, minimum = 0, maximum = 255) {
    let color_component_out = Math.max(color_component, minimum);
    return Math.min(color_component_out, maximum);
  }
}

